<?php
declare(strict_types=1);namespace App\Infrastructure\Persistence\Doctrine\Discovery;use App\Domain\Discovery\Entity\DiscoveryResource;use App\Domain\Discovery\Repository\DiscoveryResourceRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Discovery\Entity\DiscoveryResourceRecord;use Doctrine\ORM\EntityManagerInterface;final class DoctrineDiscoveryResourceRepository implements DiscoveryResourceRepositoryInterface{public function __construct(private readonly EntityManagerInterface $em){}public function save(DiscoveryResource $r):void{$record=$this->em->getRepository(DiscoveryResourceRecord::class)->findOneBy(['sourceUrl'=>$r->sourceUrl])??new DiscoveryResourceRecord();$record->id=$record->id??$r->id;$record->type=$r->type;$record->title=$r->title;$record->sourceUrl=$r->sourceUrl;$record->provider=$r->provider;$record->queryText=$r->queryText;$record->discoveredAt=$r->discoveredAt;$this->em->persist($record);}public function list(?string $type=null):array{$qb=$this->em->createQueryBuilder()->select('r')->from(DiscoveryResourceRecord::class,'r')->orderBy('r.discoveredAt','DESC')->setMaxResults(100);if($type!==null)$qb->where('r.type=:type')->setParameter('type',$type);return array_map(static fn($r)=>new DiscoveryResource($r->id,$r->type,$r->title,$r->sourceUrl,$r->provider,$r->queryText,$r->discoveredAt),$qb->getQuery()->getResult());}}
